import React, { useEffect, useState } from 'react';
import { Outlet, useLocation } from 'react-router-dom';

import AdminNavbar from './AdminNavbar';
import AdminSidebar from './AdminSidebar';
import AdminFooter from './AdminFooter';
import AdminLoading from '../common/AdminLoading';
import { useLanguage } from '../../contexts/LanguageContext';

const AdminLayout = () => {
  const location = useLocation();
  const { language } = useLanguage();
  const isKhmer = language === 'km' || language === 'kh';

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [pageChanging, setPageChanging] = useState(false);

  // Show circular loading transition when navigating between pages
  useEffect(() => {
    setPageChanging(true);
    const timer = window.setTimeout(() => {
      setPageChanging(false);
    }, 600);

    return () => window.clearTimeout(timer);
  }, [location.pathname]);

  const handleOpenSidebar = () => setSidebarOpen(true);
  const handleCloseSidebar = () => setSidebarOpen(false);

  return (
    <div className={`min-h-screen bg-[#f4f7fb] ${isKhmer ? 'font-khmer' : 'font-english'}`}>

      {/* NAVBAR */}
      <AdminNavbar onMenuClick={handleOpenSidebar} />

      {/* SIDEBAR */}
      <AdminSidebar isOpen={sidebarOpen} onClose={handleCloseSidebar} />

      {/* MAIN CONTENT */}
      <main className="min-h-screen pt-[72px] lg:ml-[270px] flex flex-col relative transition-all duration-300">

        {/* CIRCULAR PAGE TRANSITION LOADER */}
        {pageChanging && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#F8FAFC]/85 backdrop-blur-sm transition-all duration-300">
            <AdminLoading label={isKhmer ? 'កំពុងផ្ទុកទំព័រ...' : 'Loading page...'} />
          </div>
        )}

        {/* PAGE CONTENT */}
        <div className="flex-1 p-4 sm:p-6 lg:p-8">
          <div className="w-full max-w-[1600px] mx-auto">
            <Outlet />
          </div>
        </div>

        {/* FOOTER */}
        <AdminFooter />
      </main>
    </div>
  );
};

export default AdminLayout;
